// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{})
}

type ChiServerOptions struct {
	BaseURL          string
	BaseRouter       chi.Router
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, r chi.Router) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r chi.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/health", wrapper.Health)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/auth/logout", wrapper.Logout)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/auth/{provider}", wrapper.AuthDetails)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/auth/{provider}/callback", wrapper.AuthCallback)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/connectors/onboarding-requests", wrapper.OnboardConnector)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/connectors/onboarding-requests/{onboarding-id}", wrapper.GetConnectorOnboardingRequestDetails)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/entitlements", wrapper.SearchEntitlements)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/managed-systems", wrapper.ListManagedSystems)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/managed-systems", wrapper.OnboardManagedSystem)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/managed-systems/{id}", wrapper.GetManagedSystem)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/managed-systems/{id}/tenant", wrapper.ListManagedSystemTenants)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/managed-systems/{id}/tenant", wrapper.OnboardManagedSystemTenant)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/users", wrapper.GetUserDetails)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/workflows", wrapper.CreateWorkflow)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/api/v1/workflows", wrapper.SetWorkflowSchedule)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/workflows/{name}", wrapper.GetWorkflow)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/workflows/{name}/runs", wrapper.StartWorkflow)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/workflows/{name}/runs/{id}", wrapper.GetWorkflowRun)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/workflows/{name}/runs/{id}/steps/{step}/continue", wrapper.ContinueWorkflowStep)
	})

	return r
}

